-- Multi-guard request foundation: server-authoritative headcount and pricing.
alter table public.marketplace_jobs add column if not exists guard_count integer not null default 1 check (guard_count between 1 and 20);
alter table public.job_financials add column if not exists guard_count integer not null default 1 check (guard_count between 1 and 20);

create or replace function public.calculate_job_estimate(p_service_type text,p_priority public.job_priority default 'standard',p_duration_minutes integer default 60,p_scheduled_for timestamptz default null,p_requested_start text default 'scheduled',p_vacation_start_date date default null,p_vacation_end_date date default null,p_vacation_checks_per_day integer default null,p_guard_count integer default 1)
returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$
declare v_mode text:=coalesce(nullif(p_requested_start,''),'scheduled');v_minutes integer:=greatest(coalesce(p_duration_minutes,60),60);v_rate integer;v_total integer;v_fee integer;v_payout integer;v_label text;v_days integer;v_visits integer;v_fee_bps integer;v_guards integer:=coalesce(p_guard_count,1);
begin
 if v_mode='vacation' then v_guards:=1; if p_vacation_start_date is null or p_vacation_end_date is null then raise exception 'Vacation start and return dates are required.' using errcode='23514'; end if; if p_vacation_end_date<p_vacation_start_date then raise exception 'Vacation return date must be on or after the start date.' using errcode='23514'; end if; if coalesce(p_vacation_checks_per_day,0) not between 1 and 3 then raise exception 'Choose 1, 2, or 3 property checks per day.' using errcode='23514'; end if; v_days:=(p_vacation_end_date-p_vacation_start_date)+1; if v_days>60 then raise exception 'Vacation Watch can be booked for up to 60 days at a time.' using errcode='23514'; end if; v_visits:=v_days*p_vacation_checks_per_day;v_total:=v_visits*3500;v_fee_bps:=2000;v_minutes:=v_visits*30;v_label:='Vacation Watch';
 else if v_guards not between 1 and 20 then raise exception 'Choose between 1 and 20 guards.' using errcode='23514'; end if; if p_service_type='armed_guard' then v_rate:=case when v_mode='immediate' then 7000 else 5500 end;v_label:=case when v_mode='immediate' then 'Now armed guards' else 'Scheduled armed guards' end; else v_rate:=case when v_mode='immediate' then 5000 else 4000 end;v_label:=case when v_mode='immediate' then 'Now unarmed guards' else 'Scheduled unarmed guards' end;end if;v_total:=ceiling(v_rate::numeric*v_minutes/60)::int*v_guards;v_fee_bps:=case when v_mode='immediate' then 2500 else 2000 end;v_visits:=null;end if;
 v_fee:=ceiling(v_total::numeric*v_fee_bps/10000)::int;v_payout:=v_total-v_fee;
 return jsonb_build_object('service_type',case when v_mode='vacation' then 'mobile_patrol' else p_service_type end,'label',v_label,'request_mode',v_mode,'duration_minutes',v_minutes,'guard_count',v_guards,'vacation_start_date',p_vacation_start_date,'vacation_end_date',p_vacation_end_date,'vacation_checks_per_day',p_vacation_checks_per_day,'vacation_total_visits',v_visits,'subtotal_cents',v_total,'priority_surcharge_cents',0,'after_hours_surcharge_cents',0,'total_cents',v_total,'platform_fee_cents',v_fee,'agency_payout_cents',v_payout,'platform_fee_bps',v_fee_bps,'payment_status','estimate_only','payout_status','held_until_report');
end $$;

create or replace function public.get_client_job_estimate(p_property_id uuid,p_service_type text,p_priority public.job_priority default 'standard',p_duration_minutes integer default 60,p_scheduled_for timestamptz default null,p_requested_start text default 'scheduled',p_vacation_start_date date default null,p_vacation_end_date date default null,p_vacation_checks_per_day integer default null,p_guard_count integer default 1)
returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_client_id uuid;begin select id into v_client_id from public.clients where user_id=auth.uid() limit 1;if v_client_id is null then raise exception 'CLIENT_WORKSPACE_REQUIRED' using errcode='42501';end if;if not exists(select 1 from public.properties where id=p_property_id and client_id=v_client_id and archived_at is null) then raise exception 'PROPERTY_NOT_FOUND' using errcode='23514';end if;return public.calculate_job_estimate(p_service_type,p_priority,p_duration_minutes,p_scheduled_for,p_requested_start,p_vacation_start_date,p_vacation_end_date,p_vacation_checks_per_day,p_guard_count);end $$;

create or replace function public.create_marketplace_job_v2(p_property_id uuid,p_title text,p_instructions text default null,p_priority public.job_priority default 'standard',p_scheduled_for timestamptz default null,p_duration_minutes integer default 60,p_service_type text default 'unarmed_patrol',p_requested_start text default 'scheduled',p_client_contact_phone text default null,p_access_notes text default null,p_vacation_start_date date default null,p_vacation_end_date date default null,p_vacation_checks_per_day integer default null,p_guard_count integer default 1)
returns uuid language plpgsql security definer set search_path=public set row_security=off as $$ declare v_client_id uuid;v_job_id uuid;v_est jsonb;v_risk text;begin if auth.uid() is null then raise exception 'Your session has expired. Sign in again.' using errcode='28000';end if;select c.id,c.risk_level into v_client_id,v_risk from public.clients c join public.profiles p on p.id=c.user_id where c.user_id=auth.uid() and p.role='client' and p.account_status='approved' limit 1;if v_client_id is null then raise exception 'Your approved Client workspace could not be resolved.' using errcode='42501';end if;if not exists(select 1 from public.properties p where p.id=p_property_id and p.client_id=v_client_id and p.archived_at is null) then raise exception 'Select an active property owned by your Client account.' using errcode='23514';end if;if nullif(btrim(p_title),'') is null then raise exception 'Mission title is required.' using errcode='23514';end if;v_est:=public.calculate_job_estimate(p_service_type,p_priority,p_duration_minutes,p_scheduled_for,p_requested_start,p_vacation_start_date,p_vacation_end_date,p_vacation_checks_per_day,p_guard_count);insert into public.marketplace_jobs(client_id,property_id,title,instructions,priority,status,scheduled_for,duration_minutes,service_type,requested_start,client_contact_phone,access_notes,estimated_total_cents,platform_fee_cents,agency_payout_cents,pricing_snapshot,payment_status,payout_status,payout_hold_reason,client_risk_level,payout_cents,vacation_start_date,vacation_end_date,vacation_checks_per_day,vacation_total_visits,guard_count) values(v_client_id,p_property_id,btrim(p_title),nullif(btrim(p_instructions),''),'standard','open',p_scheduled_for,(v_est->>'duration_minutes')::int,v_est->>'service_type',p_requested_start,nullif(btrim(p_client_contact_phone),''),nullif(btrim(p_access_notes),''),(v_est->>'total_cents')::int,(v_est->>'platform_fee_cents')::int,(v_est->>'agency_payout_cents')::int,v_est,'estimate_only','held_until_report','payment_authorization_pending',v_risk,(v_est->>'agency_payout_cents')::int,p_vacation_start_date,p_vacation_end_date,p_vacation_checks_per_day,nullif(v_est->>'vacation_total_visits','')::int,(v_est->>'guard_count')::int) returning id into v_job_id;insert into public.job_financials(job_id,client_id,service_type,duration_minutes,subtotal_cents,priority_surcharge_cents,after_hours_surcharge_cents,total_cents,platform_fee_cents,agency_payout_cents,payment_status,payout_status,hold_reason,vacation_total_visits,guard_count) values(v_job_id,v_client_id,v_est->>'service_type',(v_est->>'duration_minutes')::int,(v_est->>'subtotal_cents')::int,0,0,(v_est->>'total_cents')::int,(v_est->>'platform_fee_cents')::int,(v_est->>'agency_payout_cents')::int,'estimate_only','held_until_report','payment_authorization_pending',nullif(v_est->>'vacation_total_visits','')::int,(v_est->>'guard_count')::int);insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(v_job_id,auth.uid(),'client_submitted',jsonb_build_object('status','open','property_id',p_property_id,'service_type',v_est->>'service_type','requested_start',p_requested_start,'guard_count',(v_est->>'guard_count')::int,'pricing',v_est));perform public.notify_role('platform_admin',v_job_id,'client_request_submitted','Client submitted request',btrim(p_title)||' entered the marketplace.','normal');return v_job_id;end $$;

revoke all on function public.calculate_job_estimate(text,public.job_priority,integer,timestamptz,text,date,date,integer,integer) from public,anon;
revoke all on function public.get_client_job_estimate(uuid,text,public.job_priority,integer,timestamptz,text,date,date,integer,integer) from public,anon;
revoke all on function public.create_marketplace_job_v2(uuid,text,text,public.job_priority,timestamptz,integer,text,text,text,text,date,date,integer,integer) from public,anon;
grant execute on function public.calculate_job_estimate(text,public.job_priority,integer,timestamptz,text,date,date,integer,integer) to authenticated,service_role;
grant execute on function public.get_client_job_estimate(uuid,text,public.job_priority,integer,timestamptz,text,date,date,integer,integer) to authenticated,service_role;
grant execute on function public.create_marketplace_job_v2(uuid,text,text,public.job_priority,timestamptz,integer,text,text,text,text,date,date,integer,integer) to authenticated,service_role;
